class Solution:

	def largestSumCycle(self, N, Edge):
		cells = []
		result = 0
		covered = {0}
		for i in range(N):
			cells = [i]
			index = i
			while True:
				if Edge[index] == -1 or Edge[index] < i:
					break
				elif Edge[index] in cells:
					eleindex = cells.index(Edge[index])
					totalSum = sum(cells[eleindex:])
					if totalSum > result:
						result = totalSum
					break
				elif Edge[index] in covered:
					break
				else:
					cells.append(Edge[index])
					index = Edge[index]
					covered.add(index)
		if result == 0:
			return -1
		return result
